"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Dev numbers for the third draft of the freeze amendment and grounding package v0.5, after step 2d became the main
system (docs/iterations.md, 2026-11-20, rules logged before running; the author approved the document updates).
Dev only, CPU; no training, no API; test and replication untouched. The second draft's numbers stay in
results/main_v04/amendment_numbers_dev.json.

A. Candidates: R-hear and S-move grounded group accuracy (95% intervals by the package's three-way cluster bootstrap)
   beside the natural dev five-part mean, for every read-out candidate including 2c and 2d.
B. Ladder and criteria with the step 2c states read-out as rung 2 (the main system's training data) and 2d as the main
   system, at the score and the decision level: G1a, G2a, G2b, G3a, G3b with absolute conditions, side rows; the
   parallel stop criteria G1a-S, G2a-S, G2b-S and the S-move pairs; the timing step (2c against 2b) and the time step
   (2d against 2c ears) on S-move.
C. Event-score differences (R-hear) for 2d and the 2c states rung.
D. Cost of grounding on natural dev: step 2 ears minus 2d (plan 7.1 interval), five-part and must-listen.
E. Words channel: 2d minus the old head (and minus 2b ears) in the event-led error rate, with intervals.
F. Decision-table rehearsal with 2d: raw differences and, for Gemini on answers, after subtracting each rival's dev
   answer-only loss (amendment 2.6).
G. The main system's follow rates by condition (R-hear; version 1 and the others).
Output: results/main_v04/amendment_numbers_2d_dev.json
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_amendment_numbers_2d_dev.py
"""
import json
import os
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_control_starts as CS  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_grounding as G  # noqa: E402
import p1v4_grounding_report as GR  # noqa: E402
import p1v4_readout as RO  # noqa: E402
import p1v4_readout_2c as R2C  # noqa: E402
import p1v4_readout_2d as R2D  # noqa: E402
import p1v4_readout_allclass as AC  # noqa: E402
import p1v4_score as S  # noqa: E402

RES = "results/main_v04"
CTL = "control (8 starts)"
PARTS = ("r_hear", "s_move")


def ci(c):
    return {"point": c["point"], "ci95": c["ci95"]}


def main():
    rows, rows_by = G.load("dev")
    groups = G.load_groups("dev")
    units = {p: [g["unit"] for g in groups if g["part"] == p] for p in PARTS}
    rh = [g for g in groups if g["part"] == "r_hear"]
    cl = GR.cluster_table(rows, "dev")
    th_all = GR.thresholds(rows)
    n2b = json.load(open(f"{RES}/readout_allclass_dev.json"))["natural"]
    n2c = json.load(open(f"{RES}/readout_2c_dev.json"))["natural"]
    n2d = json.load(open(f"{RES}/readout_2d_dev.json"))["natural"]

    def th_of(d, k):
        return (d[k]["th"]["S"], d[k]["th"]["R"])
    ro_old, ro_2b, ro_2c, ro_2d = RO.load_readouts(), AC.load_allclass(), R2C.load_2c(), R2D.load_2d()
    sec = R2D.Sec()
    zn = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    systems = {"old head": (None, ro_old, th_all["old head"]),
               "step 2 states": ("states", ro_old, th_all["states read-out"]),
               "step 2 ears": ("ears", ro_old, th_all["read-out"]),
               "2b states": ("states", ro_2b, th_of(n2b, "all-class states")),
               "2b ears": ("ears", ro_2b, th_of(n2b, "all-class ears")),
               "2c states": ("states", ro_2c, th_of(n2c, "2c states")),
               "2c ears": ("ears", ro_2c, th_of(n2c, "2c ears")),
               "2d": ("2d", ro_2d, (n2d["th"]["S"], n2d["th"]["R"]))}
    snames = []
    for s in CS.STARTS:
        r = CS.load_start(s)
        op = S.operating_point(rows, RO.scores_of(zn, "states", r))
        systems[f"start {s}"] = ("states", r, (op["th_s"], op["th_r"]))
        snames.append(f"start {s}")

    def scores(z, setting, r):
        return R2D.scores_2d(z, sec, r) if setting == "2d" else RO.scores_of(z, setting, r)
    evs, evd, dsc = {}, {}, {}
    for cond in G.MATCHED:
        z = dict(np.load(f"{G.out_dir('dev')}/l1_{cond}.npz"))
        for n, (setting, r, th) in systems.items():
            sc = scores(z, setting, r)
            dec = S.decide(sc, *th)
            evs[(n, cond)] = GR.group_eval(groups, rows_by, dec, sc)
            evd[(n, cond)] = GR.group_eval(groups, rows_by, dec, None)
            for v in ("2", "3"):
                dsc[(n, cond, v)] = np.array([sc[(g["unit"], v, g["k"])]["R"] - sc[(g["unit"], "1", g["k"])]["R"]
                                              for g in rh])

    def pu(ev, n, part, field, v=None):
        if n == CTL:
            return np.mean([pu(ev, m, part, field, v) for m in snames], 0)
        return np.array([np.mean([(ev[(n, c)][u]["pair"][v] if v else ev[(n, c)][u][field]) for c in G.MATCHED])
                         for u in units[part]])

    def dp(n, v):
        if n == CTL:
            return np.mean([dp(m, v) for m in snames], 0)
        return np.mean([dsc[(n, c, v)] for c in G.MATCHED], 0)

    def crit(part, a, b=None, minus=0.0, absdiff=None):
        us = units[part]
        if absdiff is not None:
            c = GR.criterion(us, cl, {}, lambda w: (GR.wmean(w, a) - 0.5) - abs(GR.wmean(w, absdiff) - 0.5),
                             lambda: float((a.mean() - 0.5) - abs(absdiff.mean() - 0.5)))
        elif b is not None:
            c = GR.criterion(us, cl, {}, lambda w: GR.wmean(w, a) - GR.wmean(w, b), lambda: float(a.mean() - b.mean()))
        else:
            c = GR.criterion(us, cl, {}, lambda w: GR.wmean(w, a) - minus, lambda: float(a.mean() - minus))
        return ci(c)

    res = {"A_candidates": {}, "B_criteria": {}, "C_event_score_difference": {}, "D_cost_of_grounding": {},
           "E_words_channel": {}, "F_decision_table": {}, "G_main_follow_by_condition": {}}

    # A. candidates
    loc = {}
    for cond in G.MATCHED:
        sc = GR.local_scores("dev", cond)
        for n in ("L2", "L3"):
            loc[(n, cond)] = GR.group_eval(groups, rows_by, S.decide(sc[n], *th_all[n]), sc[n])
    for n in ("L2", "L3"):
        res["A_candidates"][n] = {p: crit(p, np.array([np.mean([loc[(n, c)][u]["right"] for c in G.MATCHED])
                                                       for u in units[p]])) for p in PARTS}
    for n in ("old head", "step 2 states", "step 2 ears", "2b states", "2b ears", "2c states", "2c ears", "2d"):
        res["A_candidates"][n] = {p: crit(p, pu(evs, n, p, "right")) for p in PARTS}
    gd, ga = json.load(open(f"{RES}/grounding_dev.json")), json.load(open(f"{RES}/grounding_allclass_dev.json"))
    res["A_candidates"]["combination"] = {"r_hear": ci(gd["criteria"][
        "G1a combination: grounded group accuracy (lower bound > 0.50)"]), "s_move": None}
    res["A_candidates"]["step 2 conditional"] = {"r_hear": ci(gd["criteria"][
        "G1a conditional: grounded group accuracy (lower bound > 0.50)"]), "s_move": None}
    res["A_candidates"]["2b conditional"] = {"r_hear": ci(ga["criteria"][
        "G1a 2b conditional: R-hear grounded group accuracy (lower bound > 0.50)"]), "s_move": None}
    rd = json.load(open(f"{RES}/readout_dev.json"))["settings"]
    l1 = json.load(open(f"{RES}/decision_dev_dryrun_l1.json"))["systems"]
    natural = {"old head": l1["L1"]["primary"], "L2": l1["L2"]["primary"], "L3": l1["L3"]["primary"],
               "combination": json.load(open(f"{RES}/decision_dev_dryrun_combination.json"))["systems"]["L1"]["primary"],
               "step 2 states": rd["states"]["natural"]["primary"], "step 2 ears": rd["ears"]["natural"]["primary"],
               "step 2 conditional": json.load(open(f"{RES}/conditional_dev.json"))["inputs"]["natural"]["primary"],
               "2b states": n2b["all-class states"]["primary"], "2b ears": n2b["all-class ears"]["primary"],
               "2b conditional": n2b["all-class conditional"]["primary"], "2c states": n2c["2c states"]["primary"],
               "2c ears": n2c["2c ears"]["primary"], "2d": n2d["primary"]}
    for n, v in natural.items():
        res["A_candidates"][n]["natural_five_part_mean"] = v

    # B. criteria at both levels
    for level, ev in (("score", evs), ("decision", evd)):
        K = {}
        rhp = "r_hear"
        K["G1a: 2d R-hear grounded (lower bound > 0.5)"] = crit(rhp, pu(ev, "2d", rhp, "right"))
        K["G2a: (2c states - 0.5) - |old head - 0.5|"] = crit(rhp, pu(ev, "2c states", rhp, "conc"),
                                                              absdiff=pu(ev, "old head", rhp, "conc"))
        K["G2b: 2c states - control"] = crit(rhp, pu(ev, "2c states", rhp, "conc"), pu(ev, CTL, rhp, "conc"))
        K["G3a: step 2 states - control (presence)"] = crit(rhp, pu(ev, "step 2 states", rhp, None, "2"),
                                                            pu(ev, CTL, rhp, None, "2"))
        K["G3a absolute: step 2 states presence - 0.5"] = crit(rhp, pu(ev, "step 2 states", rhp, None, "2"), minus=0.5)
        K["G3b: 2c states - step 2 states (identity)"] = crit(rhp, pu(ev, "2c states", rhp, None, "3"),
                                                              pu(ev, "step 2 states", rhp, None, "3"))
        K["G3b absolute: 2c states identity - 0.5"] = crit(rhp, pu(ev, "2c states", rhp, None, "3"), minus=0.5)
        K["side rung 1: identity change, step 2 states - control"] = crit(rhp, pu(ev, "step 2 states", rhp, None, "3"),
                                                                          pu(ev, CTL, rhp, None, "3"))
        K["side rung 2: presence change, 2c states - step 2 states"] = crit(rhp, pu(ev, "2c states", rhp, None, "2"),
                                                                            pu(ev, "step 2 states", rhp, None, "2"))
        K["main 2d presence - 0.5"] = crit(rhp, pu(ev, "2d", rhp, None, "2"), minus=0.5)
        K["main 2d identity - 0.5"] = crit(rhp, pu(ev, "2d", rhp, None, "3"), minus=0.5)
        smp = "s_move"
        K["G1a-S: 2d S-move grounded (lower bound > 0.5)"] = crit(smp, pu(ev, "2d", smp, "right"))
        K["G2a-S: (2c states - 0.5) - |old head - 0.5|"] = crit(smp, pu(ev, "2c states", smp, "conc"),
                                                                absdiff=pu(ev, "old head", smp, "conc"))
        K["G2b-S: 2c states - control"] = crit(smp, pu(ev, "2c states", smp, "conc"), pu(ev, CTL, smp, "conc"))
        for v in ("2", "3", "4"):
            K[f"S-move pair 1 vs {v}: 2c states - control"] = crit(smp, pu(ev, "2c states", smp, None, v),
                                                                  pu(ev, CTL, smp, None, v))
        K["timing step (S-move conc): 2c states - 2b states"] = crit(smp, pu(ev, "2c states", smp, "conc"),
                                                                     pu(ev, "2b states", smp, "conc"))
        K["timing step (S-move grounded): 2c ears - 2b ears"] = crit(smp, pu(ev, "2c ears", smp, "right"),
                                                                     pu(ev, "2b ears", smp, "right"))
        K["time step (S-move grounded): 2d - 2c ears"] = crit(smp, pu(ev, "2d", smp, "right"),
                                                              pu(ev, "2c ears", smp, "right"))
        K["time step (R-hear grounded): 2d - 2c ears"] = crit(rhp, pu(ev, "2d", rhp, "right"),
                                                              pu(ev, "2c ears", rhp, "right"))
        K["main change (S-move grounded): 2d - 2b ears"] = crit(smp, pu(ev, "2d", smp, "right"),
                                                                pu(ev, "2b ears", smp, "right"))
        K["main change (R-hear grounded): 2d - 2b ears"] = crit(rhp, pu(ev, "2d", rhp, "right"),
                                                                pu(ev, "2b ears", rhp, "right"))
        means = {}
        for n in ("old head", "2b states", "2b ears", "2c states", "2c ears", "2d", CTL):
            for p in PARTS:
                means[f"{n} {p}"] = {"right": float(pu(ev, n, p, "right").mean()),
                                     "conc": float(pu(ev, n, p, "conc").mean()),
                                     "pairs": {v: float(pu(ev, n, p, None, v).mean())
                                               for v in (("2", "3") if p == "r_hear" else ("2", "3", "4"))}}
        K["_means"] = means
        res["B_criteria"][level] = K

    # C. event-score differences, R-hear (positive = the event version gets the higher event score)
    for n in ("2d", "2c states", "2c ears"):
        for v, lab in (("2", "presence"), ("3", "identity")):
            res["C_event_score_difference"][f"{n}: {lab}"] = crit("r_hear", dp(n, v))
    for v, lab in (("2", "presence"), ("3", "identity")):
        res["C_event_score_difference"][f"rung 2 2c states - step 2 states: {lab}"] = crit("r_hear", dp("2c states", v),
                                                                                         dp("step 2 states", v))

    # D. cost of grounding, natural dev
    drows = D.load_rows("dev")
    sg = S.load_groups("dev")
    dec_s2 = S.decide(GR.keyed(json.load(open(f"{RO.OUT}/scores_dev_readout.json"))), *th_all["read-out"])
    dec_2d = S.decide(GR.keyed(json.load(open(f"{RO.OUT}/scores_dev_2d.json"))), n2d["th"]["S"], n2d["th"]["R"])
    dec_2b = S.decide(RO.scores_of(zn, "ears", ro_2b), *th_of(n2b, "all-class ears"))
    dec_old = S.decide(GR.keyed(json.load(open(f"{GR.R}/l1/scores_dev.json"))), *th_all["old head"])
    Ta, Tb = S.unit_table(drows, dec_s2, sg), S.unit_table(drows, dec_2d, sg)
    for w in ("primary", "audio"):
        c = S.interval(Ta, Tb, w)
        res["D_cost_of_grounding"][w] = {"step 2 ears": S.metrics(Ta)[w], "2d": S.metrics(Tb)[w],
                                         "difference": {"point": c["point"], "ci95": c["ci95"]}}

    # E. words channel
    items = GR.word_items(drows)
    wc = {n: GR.words_channel(items, d) for n, d in (("2d", dec_2d), ("2b ears", dec_2b), ("old head", dec_old))}
    T = S.unit_table(drows, {}, sg)
    for a_, b_ in (("2d", "old head"), ("2b ears", "old head"), ("2d", "2b ears")):
        pa, pb = wc[a_]["_per_unit"], wc[b_]["_per_unit"]
        us = sorted(u for u in pa if pa[u][0] > 0 and u in T)
        n_ = np.array([pa[u][0] for u in us], float)
        ea = np.array([pa[u][1] for u in us], float)
        eb = np.array([pb.get(u, [0, 0, 0])[1] for u in us], float)
        clw = {u: tuple(T[u][f] for f in GR.FACT) for u in us}
        se, _ = GR.boot_se(us, clw, lambda w: (w * ea).sum(1) / (w * n_).sum(1) - (w * eb).sum(1) / (w * n_).sum(1))
        pt = float(ea.sum() / n_.sum() - eb.sum() / n_.sum())
        res["E_words_channel"][f"{a_} - {b_}: event-led error rate"] = {"point": pt, "ci95": [pt - 1.96 * se,
                                                                                               pt + 1.96 * se]}
    res["E_words_channel"]["by_system"] = {n: {k: v for k, v in x.items() if not k.startswith("_")} for n, x in wc.items()}

    # F. decision table with 2d
    pa = json.load(open(f"{RES}/decision_dev_dryrun_2d.json"))
    an = json.load(open(f"{RES}/decision_dev_dryrun_2d_answers.json"))
    loss = json.load(open(f"{RES}/amendment_numbers_dev.json"))["E_answer_only"]
    for r in ("B1-strong", "B2-local", "B2-fast", "B2-strong", "B3"):
        x = {"probabilities": {"diff": pa["per_rival"][r]["diff"], "ci95": pa["per_rival"][r]["ci95"]},
             "answers_raw": {"diff": an["per_rival"][r]["diff"], "ci95": an["per_rival"][r]["ci95"]}}
        if r in loss:
            lp = max(0.0, loss[r]["five_part_mean"]["loss_points"]) / 100
            x["answers_after_loss"] = {"diff": an["per_rival"][r]["diff"] - lp,
                                       "ci95": [v - lp for v in an["per_rival"][r]["ci95"]]}
        res["F_decision_table"][r] = x
    res["F_decision_table"]["row"] = {"probabilities": pa["row"], "answers": an["row"]}

    # G. main system follow rates by condition (R-hear)
    r2d = json.load(open(f"{RES}/readout_2d_dev.json"))["matched"]["score"]["r_hear"]["by_condition"]
    res["G_main_follow_by_condition"] = {c: {"version 1 follows the event": x["follow_event"],
                                             "others follow the event": x["follow_none"], "grounded": x["right"]}
                                         for c, x in r2d.items()}
    # H. hard subset AUC (package 7.3: R-hear points with natural labels 0.5-0.9, the package's batch-1 natural rerun)
    import p1v4_trust_curves as TC
    from sklearn.metrics import roc_auc_score
    hard = {q["key"]: q["real"] for q in TC.r_hear_points(rows, C.Context("dev"))
            if q["conf"] is not None and 0.5 <= q["conf"] < 0.9}
    z = dict(np.load(f"{G.out_dir('dev')}/l1_natural.npz"))
    hs = {"old head": RO.scores_of(z, None, None), "2b ears": RO.scores_of(z, "ears", ro_2b),
          "2c states": RO.scores_of(z, "states", ro_2c), "2c ears": RO.scores_of(z, "ears", ro_2c),
          "2d": R2D.scores_2d(z, sec, ro_2d)}
    hk = [k for k in hard if k in hs["old head"]]
    y = np.array([hard[k] for k in hk])
    res["H_hard_subset_auc"] = {"n_real": int(y.sum()), "n_false": int(len(y) - y.sum()),
                                **{n: float(roc_auc_score(y, [1 - s[k]["R"] for k in hk])) for n, s in hs.items()}}
    json.dump(res, open(f"{RES}/amendment_numbers_2d_dev.json", "w"), indent=1)
    print("H hard subset AUC:", json.dumps(res["H_hard_subset_auc"]))

    def fmt(x):
        return "—" if x is None else f"{x['point']:+.3f} [{x['ci95'][0]:+.3f}, {x['ci95'][1]:+.3f}]"
    for n, x in res["A_candidates"].items():
        print(f"A {n:18s} R {fmt(x['r_hear'])} S {fmt(x['s_move'])} natural {x['natural_five_part_mean']:.3f}")
    for level, K in res["B_criteria"].items():
        for k, v in K.items():
            if not k.startswith("_"):
                print(f"B {level:8s} {k}: {fmt(v)}")
    for k, v in res["C_event_score_difference"].items():
        print(f"C {k}: {fmt(v)}")
    for w, x in res["D_cost_of_grounding"].items():
        print(f"D {w}: step 2 ears {x['step 2 ears']:.4f} 2d {x['2d']:.4f} diff {fmt(x['difference'])}")
    for k, v in res["E_words_channel"].items():
        if k != "by_system":
            print(f"E {k}: {fmt(v)}")
    for n, x in res["E_words_channel"]["by_system"].items():
        print(f"E {n}: event-led {x['event_led_rate']:.4f} blind {x['event_blind_rate']:.4f}; by type " + json.dumps(
            {t: [y['event_led'], y['event_blind'], y['n']] for t, y in x["by_type"].items() if y['event_led'] or y['event_blind']}))
    for r, x in res["F_decision_table"].items():
        print(f"F {r}: {json.dumps(x)}")
    for c, x in res["G_main_follow_by_condition"].items():
        print(f"G {c}: {json.dumps({k: round(v, 3) for k, v in x.items()})}")


if __name__ == "__main__":
    main()
